/**
 * Codex PreToolUse policy for generated files.
 *
 * Owns one narrow rule: an apply_patch call may not update or delete an existing file whose header
 * says it is generated or must not be edited manually. Regeneration commands remain available,
 * because the hook deliberately inspects patch targets rather than shell side effects.
 */
import { readFileSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const GENERATED_HEADER_PATTERN = /(?:generated(?: file)?[^\n]{0,100}do not edit|generated by[^\n]{0,100}do not edit|regenerate rather than edit|do not edit this file manually)/i
const REPOSITORY_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..')

/** Returns existing files an apply_patch command would update or delete. */
export function patchTargets(command) {
  const targets = []
  const pattern = /^\*\*\* (?:Update|Delete) File: (.+)$/gm
  let match

  while ((match = pattern.exec(command)) !== null) {
    targets.push(match[1])
  }

  return [...new Set(targets)]
}
/** Whether the file's leading comment declares it generated or manually immutable. */
export function hasGeneratedHeader(filePath) {
  try {
    return GENERATED_HEADER_PATTERN.test(readFileSync(filePath, 'utf8').slice(0, 4096))
  } catch {
    // A target may disappear after the patch is constructed; only existing generated files are
    // this policy's responsibility, and apply_patch owns reporting an unreadable/missing target.
    return false
  }
}

/** Whether a path is inside Capacitor's disposable generated Android tree. */
export function isGeneratedAndroidPath(filePath, repositoryRoot = REPOSITORY_ROOT) {
  const relativePath = path.relative(repositoryRoot, filePath)
  return relativePath === path.join('apps', 'mobile', 'android')
    || relativePath.startsWith(`${path.join('apps', 'mobile', 'android')}${path.sep}`)
}

/** Evaluates the supported PreToolUse event and returns a Codex hook response when it must deny. */
export function evaluateGeneratedFilePolicy(event, repositoryRoot = REPOSITORY_ROOT) {
  if (event.hook_event_name !== 'PreToolUse' || event.tool_name !== 'apply_patch') return null
  if (typeof event.tool_input?.command !== 'string') return null

  const blocked = patchTargets(event.tool_input.command)
    .filter((target) => {
      const targetPath = path.resolve(event.cwd, target)
      return hasGeneratedHeader(targetPath) || isGeneratedAndroidPath(targetPath, repositoryRoot)
    })

  if (blocked.length === 0) return null

  return {
    hookSpecificOutput: {
      hookEventName: 'PreToolUse',
      permissionDecision: 'deny',
      permissionDecisionReason: `Edit the generator and regenerate instead of patching: ${blocked.join(', ')}`
    }
  }
}

/** Reads one hook event from stdin. Hook protocol output is the only text written to stdout. */
async function main() {
  const event = JSON.parse(await readStdin())
  const response = evaluateGeneratedFilePolicy(event)
  if (response) process.stdout.write(JSON.stringify(response))
}

function readStdin() {
  return new Promise((resolve, reject) => {
    let input = ''
    process.stdin.setEncoding('utf8')
    process.stdin.on('data', (chunk) => { input += chunk })
    process.stdin.on('end', () => resolve(input))
    process.stdin.on('error', reject)
  })
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main().catch((error) => {
    process.stdout.write(JSON.stringify({ systemMessage: `Generated-file hook failed: ${error.message}` }))
  })
}
